use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let str_input = input.as_str().unwrap();
    let mut parts = str_input.split('.');
    let mut cents = 0;
    let mut sign = 1;
    let mut number = 0;

    if parts.len() == 1 {
        let num_str = parts[0].to_string();
        if num_str.starts_with('-') {
            sign = -1;
            num_str = num_str[1..].to_string();
        }
        for c in num_str.chars() {
            if c.is_digit(10) {
                let digit = c.to_digit(10).unwrap();
                cents = cents * 10 + digit;
            }
        }
    } else if parts.len() == 2 {
        let num_str = parts[0].to_string();
        let num_str = parts[1].to_string();
        if num_str.starts_with('-') {
            sign = -1;
            num_str = num_str[1..].to_string();
        }
        for c in num_str.chars() {
            if c.is_digit(10) {
                let digit = c.to_digit(10).unwrap();
                cents = cents * 10 + digit;
            }
        }
    } else {
        return Value::Null;
    }

    Value::Number(serde_json::Number::from(cents * sign))
}
